const split = (text: string) => text.split("~").map((part) => part.trim());
const pos: Record<string, string> = { n: "noun", u: "uncountable noun", pl: "plural noun", vt: "verb", vi: "verb", adj: "adjective", adv: "adverb", phrase: "phrase" };
const usage = (word: string, code: string, collocations: string[]): string => {
  if (code === "u") return `Trong nghĩa đã ghi, ${word} thường không đếm được; dùng some hoặc much và tránh tự thêm -s. Một số từ có nghĩa đếm được khác; xem ngữ cảnh trước khi đổi dạng.`;
  if (code === "pl") return `${word} đang ở dạng số nhiều; dùng động từ số nhiều khi nó là chủ ngữ và không đặt a/an trước dạng này.`;
  if (code === "adj") return `${word} là tính từ trong nghĩa này; dùng với danh từ hoặc sau be, không dùng nó thay cho danh từ chỉ khái niệm.`;
  if (code === "adv") return `${word} là trạng từ; kiểm tra vị trí trong câu. Cụm tự nhiên để luyện: ${collocations[0]}.`;
  if (code === "vt") return `${word} là động từ trong nghĩa này; xác định tân ngữ và chia theo thì. Học cả cụm ${collocations[0]} để tránh ghép sai từ.`;
  if (code === "vi") return `${word} không tự nhận tân ngữ trực tiếp trong nghĩa đã ghi; giữ giới từ khi cần, như ${collocations[0]}.`;
  if (code === "phrase") return `Học ${word} như một cụm hoàn chỉnh; không dịch từng từ hoặc tự thay giới từ. Mẫu sử dụng: ${collocations[0]}.`;
  return `${word} là danh từ trong nghĩa đã ghi; phân biệt với từ cùng họ, dùng a/an hoặc dạng số nhiều khi ngữ cảnh yêu cầu. Cụm nên nhớ: ${collocations[0]}.`;
};

export const expandedVocabularyBank: (VocabularyEntry & { source: "ai"; quality: "ai-unreviewed" })[] = Object.entries(rows).flatMap(([topic, block]) => block.trim().split("\n").map((row) => {
  const [word, meaning, definition, ipa, code, cefr, phrases, examples, family, synonyms] = row.split("|");
  if (![word, meaning, definition, ipa, code, cefr, phrases, examples, family, synonyms].every(Boolean)) throw new Error(`Incomplete vocabulary row: ${word}`);
  const collocations = split(phrases!);
  return {
    id: `vocab-v3-${topic.toLowerCase()}-${word!.replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "")}`,
    word: word!, meaning: meaning!, definition: definition!, ipa: ipa!, partOfSpeech: pos[code!]!, cefr: cefr as Cefr, topic,
    collocations, examples: split(examples!), family: split(family!), synonyms: split(synonyms!),
    commonError: usage(word!, code!, collocations), register: cefr === "C1" ? "academic" : "neutral",
    source: "ai", quality: "ai-unreviewed",
  };
}));
